import{_ as s,C as o,o as d,c as r,j as t,a as i,E as n,a2 as c}from"./chunks/framework.sc8Z_ZE3.js";const y=JSON.parse('{"title":"Set up a benchmark workspace","description":"","frontmatter":{},"headers":[],"relativePath":"start/benchmark-workspace.md","filePath":"start/benchmark-workspace.md"}'),h={name:"start/benchmark-workspace.md"};function l(p,e,u,f,b,m){const a=o("Badge");return d(),r("div",null,[e[0]||(e[0]=t("h1",{id:"set-up-a-benchmark-workspace",tabindex:"-1"},[i("Set up a benchmark workspace "),t("a",{class:"header-anchor",href:"#set-up-a-benchmark-workspace","aria-label":'Permalink to "Set up a benchmark workspace"'},"​")],-1)),n(a,{type:"tried",text:"In real runs"}),e[1]||(e[1]=c(` How we measure Octryx AI against a coding agent on its own, every setting we use, and how to run it yourself. The results are on <a href="/docs/start/status#results">Status and results</a>.<h2 id="the-workspace" tabindex="-1">The workspace <a class="header-anchor" href="#the-workspace" aria-label="Permalink to &quot;The workspace&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Setting</th><th>Value</th></tr></thead><tbody><tr><td>Workspace</td><td>&quot;Octryx Bench&quot;, on a local stack on one Mac</td></tr><tr><td><a href="/docs/security/data-classes">Data class</a></td><td>Internal</td></tr><tr><td>Coding agent</td><td>Claude Code on a person&#39;s Claude subscription (<a href="/docs/concepts/workspaces#seats-and-the-governed-route">seat</a>); every case runs Sonnet 5.5</td></tr><tr><td>Review</td><td>on the seat, with the platform&#39;s default review model (Sonnet 5.5), no Workspace override; an admin can change the default for the installation, and a Workspace or a workflow step can override it</td></tr><tr><td>Workflows</td><td>bugs: <strong>Bug fix with a reproduction test</strong>; stories: <strong>Story / epic delivery</strong>, both the shipped definitions</td></tr><tr><td><a href="/docs/concepts/workflows#size-classes">Size classes</a></td><td>from the workflow definition, default M; the bug cases are S, the story cases M</td></tr><tr><td>Browser and system test</td><td>the bug workflow always runs the declared system test, and the bug must be red on the old code first; for stories the browser test is skipped in S unless the item is labelled <code>ui-visible</code> or <code>hands-on</code></td></tr><tr><td>Budget</td><td>none</td></tr></tbody></table><p>An app that declares no system test counts that criterion as &quot;n/a&quot;, listed separately.</p><h2 id="the-cases" tabindex="-1">The cases <a class="header-anchor" href="#the-cases" aria-label="Permalink to &quot;The cases&quot;">​</a></h2><ul><li>Three apps in one repository: a Flutter web app (a coffee-brewing app), a small Python app and a small Node app.</li><li>Each case pins a base branch and a base commit. A case is refused when the branch has moved, so it cannot change silently.</li><li><strong>Nightly set</strong>: 6 cases, one bug (S) and one small story (M) per stack.</li><li><strong>On-demand set</strong>: 11 more Flutter cases, taken from real runs and approved by a person.</li><li>Each case has a fixed clone folder on the device, on the device&#39;s <a href="/docs/install/launcher#make-the-machine-a-device">folder allow list</a>.</li></ul><h2 id="the-benchmark-repository" tabindex="-1">The benchmark repository <a class="header-anchor" href="#the-benchmark-repository" aria-label="Permalink to &quot;The benchmark repository&quot;">​</a></h2><p>The cases are public at <a href="https://github.com/octryx-ai/octryx-bench" target="_blank" rel="noreferrer">github.com/octryx-ai/octryx-bench</a>:</p><ul><li>the three apps on <code>main</code>;</li><li>each case&#39;s base as its own branch or tag;</li><li>a copy of the case briefs, the same text the runs start from (some are in German, as they were written).</li></ul><div class="language-sh vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">sh</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">git</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> clone</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> https://github.com/octryx-ai/octryx-bench.git</span></span></code></pre></div><table tabindex="0"><thead><tr><th>Case</th><th>Base branch</th><th>Commit</th></tr></thead><tbody><tr><td>flutter-bug</td><td><code>base/flutter-bug-env</code></td><td><code>ca315d2cd7fc99d221d6b87304bd3f66dab165b6</code></td></tr><tr><td>flutter-story</td><td><code>base/flutter-story-env</code></td><td><code>2d6437e9e4cb1af2466dee82ad425839f7ba17f4</code></td></tr><tr><td>python-bug</td><td><code>base/python-bug-env</code></td><td><code>06d99c7103da2d84082b34f19d9bbffc7cfbdc13</code></td></tr><tr><td>python-story</td><td><code>base/python-story-env</code></td><td><code>033a3f3d9accfc3c96bcd553cd1605578feabe4c</code></td></tr><tr><td>node-bug</td><td><code>base/node-bug-env</code></td><td><code>d43311f0afcbba49bde863e0597ea3d0ce4e22f2</code></td></tr><tr><td>node-story</td><td><code>base/node-story-env</code></td><td><code>16f6cefb833fc2204e9496ecb9df78009f9c486c</code></td></tr><tr><td>bug-cof-73</td><td><code>base/bug-cof-73-env</code></td><td><code>bff9cf1ef48d4f13ec513a3cad2a526b3b219b8f</code></td></tr><tr><td>story-cof-45</td><td><code>base/story-cof-45-env</code></td><td><code>2b8bd43d5f5a88ebb1737f535c3a2a8e862bf7e3</code></td></tr><tr><td>story-cof-46</td><td><code>base/story-cof-46-env</code></td><td><code>1326b808601022494b6d7ec96c4efea8ab5d8649</code></td></tr><tr><td>story-cof-47</td><td><code>base/story-cof-47-env</code></td><td><code>0299d1b54dc0ea7bd83de7751e60dd810554c565</code></td></tr><tr><td>story-cof-48</td><td><code>base/story-cof-48-env</code></td><td><code>7b4f12c30079900b6956fbb76e86adc4c8cd3a04</code></td></tr><tr><td>story-cof-49</td><td><code>base/story-cof-49-env</code></td><td><code>4a33fa1a20ff3ff546d4c1202c63c02199a580f7</code></td></tr><tr><td>story-cof-50</td><td><code>base/story-cof-50-env</code></td><td><code>5e02c9869f008b3f186101047d1ac11ea1aa91bc</code></td></tr><tr><td>story-cof-75</td><td><code>base/story-cof-75-env</code></td><td><code>781823b2a205e22aa07350f115bba6448c84d2e1</code></td></tr><tr><td>story-cof-77</td><td><code>base/story-cof-77-env</code></td><td><code>8fd718321c61476095775b15a050069397163f83</code></td></tr><tr><td>story-cof-78</td><td><code>base/story-cof-78-env</code></td><td><code>2a2f0226b7c81eaf07a8cb2107ff02aaaea84e62</code></td></tr><tr><td>story-cof-81</td><td><code>base/story-cof-81-env</code></td><td><code>82fb0fd808fd9453ca1e27582f5aec0af307d96d</code></td></tr></tbody></table><p>Each base branch is one commit, and <code>cases/cases.json</code> in the repository names the same commit per case. Check out a base before you run its case; the commit must match, or the result is not comparable.</p><h2 id="a-round" tabindex="-1">A round <a class="header-anchor" href="#a-round" aria-label="Permalink to &quot;A round&quot;">​</a></h2><p>The suite runs nightly, after the merge gate, or on demand, one case after another or all at once. For each case it:</p><ol><li>resets the clone to its base (leftovers are stashed, never deleted);</li><li>creates a new work item through the API;</li><li>starts the run on the device and watches it, with no human step;</li><li>at the end, stops a run that is still open and closes its pull request; the branch stays.</li></ol><h2 id="what-is-measured" tabindex="-1">What is measured <a class="header-anchor" href="#what-is-measured" aria-label="Permalink to &quot;What is measured&quot;">​</a></h2><p><strong>Outcome per case</strong></p><ul><li><strong>completed</strong>: done, or a pull request is open;</li><li><strong>paused</strong>: paused or waiting for a person for more than 3 minutes, with the cause: platform, agent, environment or person;</li><li><strong>failed</strong>: stopped, failed, or over the 45-minute limit.</li></ul><p><strong>Time and cost</strong> come from the run&#39;s events: wall time, and cost at list price for seat use, with real API cost reported separately. They are also exported as Prometheus metrics.</p><p><strong>A rubric</strong> (version 2) checks yes-or-no criteria from the events and the pull request:</p><ul><li><strong>proven</strong>: a story counts only with a green last pipeline, nothing unproven, and a new or changed test in the pull request;</li><li>system test green;</li><li>review passed;</li><li>pull request opened;</li><li>no intervention.</li></ul><p>Each round, people check 2 sampled cases by hand, and the report shows how often they agree with the rubric.</p><h2 id="compared-with-plain-claude-code" tabindex="-1">Compared with plain Claude Code <a class="header-anchor" href="#compared-with-plain-claude-code" aria-label="Permalink to &quot;Compared with plain Claude Code&quot;">​</a></h2><p>The same bug and the same story go to plain <code>claude -p</code> with the same model, base commit, brief and machine. Reference figures: the bug in 73 s for $0.26, the story in 208 s for $0.33. The report shows the factor Octryx AI ÷ plain.</p><p>Plain runs vary a lot: the same story took between 9.5 and 23 minutes within one hour. Compare against a plain control <strong>started at the same time</strong>, not only against fixed numbers.</p><h2 id="run-a-round-yourself" tabindex="-1">Run a round yourself <a class="header-anchor" href="#run-a-round-yourself" aria-label="Permalink to &quot;Run a round yourself&quot;">​</a></h2><p>The harness that runs the rounds is in the product repository, under <code>scripts/e2e</code>. The cases are in <code>scripts/e2e/cases.json</code>.</p><p><strong>You need</strong></p><ol><li>A running stack: see <a href="/docs/install/docker">Docker Compose</a>. The demo data is not needed.</li><li>In the Workspace, the workflows <strong>Bug fix with a reproduction test</strong> and <strong>Story / epic delivery</strong>, and the seat models admitted.</li><li>A device registered with the stack and running <code>octryx-claude</code>, with Claude Code signed in to a Claude subscription (<a href="/docs/install/launcher">Launcher and devices</a>). The cases use the seat and Sonnet 5.5.</li><li>One clone folder per case, <code>&lt;cases_dir&gt;/e2e-&lt;case id&gt;</code> (default <code>~/bench-cases</code>), with a clone of <code>octryx-bench</code> and the case&#39;s base branch <code>base/&lt;case id&gt;-env</code> checked out. Every folder must be on the device&#39;s <a href="/docs/install/launcher#make-the-machine-a-device">folder allow list</a>.</li><li>An admin API key for the stack, in a file: <code>~/.octryx-e2e/api-key</code>, or the path in <code>OCTRYX_E2E_KEY_FILE</code>. The key is never written anywhere.</li></ol><p><strong>Your installation&#39;s values</strong> go into <code>scripts/e2e/cases.local.json</code>, which Git ignores. <code>cases.json</code> ships with the placeholders <code>&lt;workspace-id&gt;</code> and <code>&lt;device-id&gt;</code>; the local file sets <code>defaults</code> (<code>api</code>, <code>project_id</code>, <code>device_id</code>, <code>cases_dir</code>, <code>stack_checkout</code>), can change single cases under <code>cases</code>, and has an <code>env</code> block. A setting is taken from the environment first, then from that <code>env</code> block, then from the default. The README in <code>scripts/e2e</code> has an example under &quot;Your installation&quot;.</p><table tabindex="0"><thead><tr><th>Setting</th><th>Default</th></tr></thead><tbody><tr><td><code>OCTRYX_E2E_KEY_FILE</code></td><td><code>~/.octryx-e2e/api-key</code></td></tr><tr><td><code>OCTRYX_E2E_OUT</code> (the report folder; <code>--out</code> wins)</td><td><code>./e2e-reports</code></td></tr><tr><td><code>OCTRYX_E2E_TRANSCRIPTS</code></td><td><code>~/.claude/projects</code></td></tr><tr><td><code>OCTRYX_E2E_PROMETHEUS</code></td><td><code>http://127.0.0.1:24290</code></td></tr></tbody></table><p><strong>Run it</strong> from the root of the product repository:</p><div class="language-sh vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">sh</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">python3</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> -m</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> scripts.e2e.nightly</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> --dry-run</span><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;">                         # checks cases, folders and bases, starts nothing</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">python3</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> -m</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> scripts.e2e.nightly</span><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;">                                   # the 6 nightly cases</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">python3</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> -m</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> scripts.e2e.nightly</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> --schedule</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> on-demand</span><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;">              # the 11 on-demand cases</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">python3</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> -m</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> scripts.e2e.nightly</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> --schedule</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> all</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> --all-parallel</span><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;">     # all 17 at once</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">python3</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> -m</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> scripts.e2e.nightly</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> --cases</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> flutter-bug</span><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;">               # one case by its id</span></span></code></pre></div><p>Without <code>--all-parallel</code>, the cases of one stack run one after another, and two stacks run at the same time. For a daily round we use <code>scripts/e2e/nightly-e2e.sh</code>, a scheduler for a Mac (screen session, 03:30). A case whose branch has moved off its base commit, or whose folder is not on the allow list, is not run, and the report says why.</p><p><strong>The report</strong> lands in the report folder:</p><ul><li><code>latest.md</code> and <code>&lt;date&gt;.md</code>: the outcome per case (completed, paused, failed), wall time and cost, and the <a href="#what-is-measured">rubric</a> criteria;</li><li><code>&lt;date&gt;.json</code>: the source for the trend across rounds;</li><li><code>e2e.prom</code>: the same figures as Prometheus metrics;</li><li><code>&lt;date&gt;.audit.json</code> and <code>review/index.html</code>: the 2 sampled cases for the check by hand, with a read-only page to go through them;</li><li><code>summary.txt</code>: a short summary of the round.</li></ul><p><code>python3 -m scripts.e2e.rescore e2e-reports/&lt;date&gt;.json</code> scores a finished round again with the current rubric.</p><h2 id="do-it-yourself" tabindex="-1">Do it yourself <a class="header-anchor" href="#do-it-yourself" aria-label="Permalink to &quot;Do it yourself&quot;">​</a></h2><p>The same method on your own repository:</p><ol><li>Pin a base commit.</li><li>Write one bug with a clear reproduction and one small story with at most three acceptance criteria.</li><li>Start plain <code>claude -p</code> with the same brief and a run in Octryx AI at the same moment, on the same machine and model.</li><li>Compare wall time, cost, and whether the result is proven by tests: a test red on the old code and green with the fix, and the declared tests green.</li></ol><p>Run each case more than once: a single run says little.</p>`,43))])}const g=s(h,[["render",l]]);export{y as __pageData,g as default};
